-- pg-tenant-guard 0.1.0
-- https://github.com/shivamlaur022/pg-tenant-guard
--
-- Generated by scripts/build.sh from sql/*.sql. Do not edit by hand.
--
-- Install:  psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f pg-tenant-guard.sql
-- Supabase: paste into the SQL editor, or copy into a migration.
--
-- Runs in one transaction. Safe to run again on a database that already has
-- this version installed: objects are created with IF NOT EXISTS or
-- CREATE OR REPLACE, and seed rows use ON CONFLICT DO NOTHING.

begin;

-- ------------------------------------------------------------------------
-- sql/001_schema.sql
-- ------------------------------------------------------------------------

-- pg-tenant-guard 001: schema and caller identity.
--
-- Everything this kit creates lives in the tenant_guard schema so it does not
-- collide with application objects and can be dropped in one statement.

create schema if not exists tenant_guard;

comment on schema tenant_guard is
  'pg-tenant-guard: tenant isolation (RLS) and tenant lock helpers';

-- Nothing in this schema is reachable by default. Client roles are granted
-- access explicitly with tenant_guard.grant_to() (see the grants file).
revoke all on schema tenant_guard from public;

-- Installed version. scripts/build.sh reads the version from this function
-- for the header of dist/pg-tenant-guard.sql.
create or replace function tenant_guard.version()
returns text
language sql
immutable
set search_path = ''
as $$ select '0.1.0' $$;

comment on function tenant_guard.version() is 'Installed pg-tenant-guard version';

-- Returns the id of the end user making the current request, or NULL for an
-- anonymous request. Resolution order:
--
--   1. auth.uid(), when such a function exists (Supabase).
--   2. The PostgREST JWT settings: request.jwt.claim.sub, then the "sub" key
--      of request.jwt.claims.
--   3. The tenant_guard.user_id setting, for applications that connect to
--      plain PostgreSQL and run `set local tenant_guard.user_id = '...'`
--      at the start of each transaction.
--
-- The function only reads session state, so it runs with the privileges of
-- the caller (SECURITY INVOKER). To use a different source of identity,
-- replace it with `create or replace function tenant_guard.current_user_id()`;
-- every other helper goes through this function.
--
-- PL/pgSQL plans statements lazily, so the reference to auth.uid() below is
-- only resolved when that branch runs. The function can therefore be created
-- on databases that have no auth schema.
create or replace function tenant_guard.current_user_id()
returns uuid
language plpgsql
stable
set search_path = ''
as $$
declare
  claim text;
begin
  if to_regprocedure('auth.uid()') is not null then
    return auth.uid();
  end if;

  claim := nullif(current_setting('request.jwt.claim.sub', true), '');

  if claim is null then
    claim := nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub';
  end if;

  if claim is null then
    claim := nullif(current_setting('tenant_guard.user_id', true), '');
  end if;

  -- An id that is not a valid uuid raises invalid_text_representation
  -- (22P02). Failing loudly is deliberate: a malformed identity must never
  -- be treated as anonymous or matched loosely.
  return claim::uuid;
end;
$$;

comment on function tenant_guard.current_user_id() is
  'Id of the requesting end user: auth.uid() if present, else JWT claim sub, else the tenant_guard.user_id setting';

-- Internal: checks that a relation is a table with a `tenant_id uuid` column
-- and returns that column's attribute number. Used by the DDL helpers.
create or replace function tenant_guard.assert_tenant_table(tbl regclass)
returns smallint
language plpgsql
stable
set search_path = ''
as $$
declare
  v_relkind "char";
  v_type    regtype;
  v_attnum  smallint;
begin
  select c.relkind into v_relkind
  from pg_catalog.pg_class c
  where c.oid = tbl;

  if v_relkind is null or v_relkind not in ('r', 'p') then
    raise exception '% is not a table', tbl
      using errcode = 'wrong_object_type';
  end if;

  select a.atttypid::regtype, a.attnum into v_type, v_attnum
  from pg_catalog.pg_attribute a
  where a.attrelid = tbl
    and a.attname = 'tenant_id'
    and a.attnum > 0
    and not a.attisdropped;

  if v_type is null then
    raise exception '% has no tenant_id column', tbl
      using errcode = 'undefined_column';
  end if;

  if v_type <> 'uuid'::regtype then
    raise exception '%.tenant_id must be uuid, not %', tbl, v_type
      using errcode = 'datatype_mismatch';
  end if;

  return v_attnum;
end;
$$;

comment on function tenant_guard.assert_tenant_table(regclass) is
  'Internal: raises unless the relation is a table with a tenant_id uuid column';

-- ------------------------------------------------------------------------
-- sql/010_tenants.sql
-- ------------------------------------------------------------------------

-- pg-tenant-guard 010: tenants, roles, memberships and membership helpers.

-- Roles a member can hold inside a tenant. Roles are global (the same set for
-- every tenant); what each role may do is defined in 020_permissions.sql.
create table if not exists tenant_guard.roles (
  name        text primary key check (name ~ '^[a-z][a-z0-9_]*$'),
  description text
);

insert into tenant_guard.roles (name, description) values
  ('owner',  'Full control of the tenant, including members and settings'),
  ('editor', 'Can read and change tenant data'),
  ('viewer', 'Can read tenant data')
on conflict (name) do nothing;

create table if not exists tenant_guard.tenants (
  id         uuid primary key default gen_random_uuid(),
  name       text not null check (btrim(name) <> ''),
  created_at timestamptz not null default now()
);

create table if not exists tenant_guard.tenant_members (
  tenant_id  uuid not null references tenant_guard.tenants (id) on delete cascade,
  user_id    uuid not null,
  role       text not null references tenant_guard.roles (name) on update cascade,
  created_at timestamptz not null default now(),
  primary key (tenant_id, user_id)
);

-- Every access check looks up the current user's memberships. This index
-- answers "which tenants does user X belong to, and with which role" with an
-- index-only scan.
create index if not exists tenant_members_user_idx
  on tenant_guard.tenant_members (user_id) include (tenant_id, role);

comment on table tenant_guard.tenants is 'One row per tenant (organisation, workspace, school, ...)';
comment on table tenant_guard.tenant_members is 'Which users belong to which tenant, and with which role';
comment on table tenant_guard.roles is 'Roles a member can hold; permissions per role live in role_permissions';

-- Membership helpers ---------------------------------------------------------
--
-- These read tenant_members, which is itself protected by RLS. They are
-- SECURITY DEFINER so that a policy on tenant_members can call them without
-- recursing into its own policy, and so that callers never need direct access
-- to the membership table. Each one pins search_path to '' and fully
-- qualifies every name, so a caller cannot redirect a lookup by creating
-- objects in a schema that appears earlier on their search_path.

create or replace function tenant_guard.is_member(tenant_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from tenant_guard.tenant_members m
    where m.tenant_id = is_member.tenant_id
      and m.user_id = tenant_guard.current_user_id()
  );
$$;

comment on function tenant_guard.is_member(uuid) is
  'True when the current user is a member of the tenant';

create or replace function tenant_guard.member_role(tenant_id uuid)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select m.role
  from tenant_guard.tenant_members m
  where m.tenant_id = member_role.tenant_id
    and m.user_id = tenant_guard.current_user_id();
$$;

comment on function tenant_guard.member_role(uuid) is
  'Role of the current user in the tenant, or NULL when not a member';

-- Set-returning form for policies; see the note on permitted_tenant_ids() in
-- 020_permissions.sql for why policies use `= any (array(select ...))`.
create or replace function tenant_guard.my_tenant_ids()
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select m.tenant_id
  from tenant_guard.tenant_members m
  where m.user_id = tenant_guard.current_user_id();
$$;

comment on function tenant_guard.my_tenant_ids() is
  'Ids of every tenant the current user belongs to';

-- Creates a tenant and makes the calling user its owner, in one step. Clients
-- have no INSERT privilege on tenants, so this is the only self-service way to
-- create one.
create or replace function tenant_guard.create_tenant(name text)
returns uuid
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_user   uuid := tenant_guard.current_user_id();
  v_tenant uuid;
begin
  if v_user is null then
    raise exception 'create_tenant requires an authenticated user'
      using errcode = 'insufficient_privilege';
  end if;

  insert into tenant_guard.tenants (name) values (create_tenant.name)
  returning id into v_tenant;

  insert into tenant_guard.tenant_members (tenant_id, user_id, role)
  values (v_tenant, v_user, 'owner');

  return v_tenant;
end;
$$;

comment on function tenant_guard.create_tenant(text) is
  'Creates a tenant owned by the current user and returns its id';

-- Row-level security on the kit's own tables ---------------------------------

alter table tenant_guard.tenants enable row level security;
alter table tenant_guard.tenant_members enable row level security;
alter table tenant_guard.roles enable row level security;

drop policy if exists tenants_select on tenant_guard.tenants;
create policy tenants_select on tenant_guard.tenants
  for select
  using (id = any (array(select tenant_guard.my_tenant_ids())));

-- Members can see who else belongs to their tenants.
drop policy if exists tenant_members_select on tenant_guard.tenant_members;
create policy tenant_members_select on tenant_guard.tenant_members
  for select
  using (tenant_id = any (array(select tenant_guard.my_tenant_ids())));

-- Policies for changing tenants and memberships are permission-based and
-- defined in 020_permissions.sql.

-- Role definitions are not secret; anyone with access to the schema may read them.
drop policy if exists roles_select on tenant_guard.roles;
create policy roles_select on tenant_guard.roles
  for select
  using (true);

-- ------------------------------------------------------------------------
-- sql/020_permissions.sql
-- ------------------------------------------------------------------------

-- pg-tenant-guard 020: role permissions with view/edit access.
--
-- A permission is a free-form name, usually the name of a table or feature
-- ("projects", "invoices", "reports.export"). Each role is granted a set of
-- permissions, each with an access mode:
--
--   view  read only
--   edit  read and write (edit implies view)
--
-- The special permission '*' matches every permission except the built-in
-- ones, whose names start with "tenant_guard.":
--
--   tenant_guard.members  add, change or remove members of a tenant
--   tenant_guard.tenant   change the tenant row itself (e.g. rename it)
--
-- The exception exists so that granting a role '*' edit ("can change all
-- tenant data") does not silently let it promote itself to owner. Built-in
-- permissions must always be granted explicitly.

do $$
begin
  create type tenant_guard.access_mode as enum ('view', 'edit');
exception
  when duplicate_object then null;
end;
$$;

comment on type tenant_guard.access_mode is
  'Access level for a permission; edit implies view (the enum is ordered)';

create table if not exists tenant_guard.role_permissions (
  role       text not null references tenant_guard.roles (name) on update cascade on delete cascade,
  permission text not null check (btrim(permission) <> ''),
  access     tenant_guard.access_mode not null,
  primary key (role, permission)
);

comment on table tenant_guard.role_permissions is
  'Permissions granted to each role. permission = ''*'' matches everything except tenant_guard.* permissions';

insert into tenant_guard.role_permissions (role, permission, access) values
  ('owner',  '*',                    'edit'),
  ('owner',  'tenant_guard.members', 'edit'),
  ('owner',  'tenant_guard.tenant',  'edit'),
  ('editor', '*',                    'edit'),
  ('viewer', '*',                    'view')
on conflict (role, permission) do nothing;

alter table tenant_guard.role_permissions enable row level security;

-- Like roles, the permission matrix is configuration, not tenant data.
drop policy if exists role_permissions_select on tenant_guard.role_permissions;
create policy role_permissions_select on tenant_guard.role_permissions
  for select
  using (true);

-- True when the current user's role in the tenant grants `permission` with
-- at least `mode` access. NULL arguments return false.
--
-- Comparing enum values (`rp.access >= mode`) relies on the declaration
-- order of access_mode: view < edit.
create or replace function tenant_guard.has_permission(
  tenant_id  uuid,
  permission text,
  mode       tenant_guard.access_mode default 'view'
)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from tenant_guard.tenant_members m
    join tenant_guard.role_permissions rp on rp.role = m.role
    where m.tenant_id = has_permission.tenant_id
      and m.user_id = tenant_guard.current_user_id()
      and rp.access >= has_permission.mode
      and (
        rp.permission = has_permission.permission
        or (rp.permission = '*' and not starts_with(has_permission.permission, 'tenant_guard.'))
      )
  );
$$;

comment on function tenant_guard.has_permission(uuid, text, tenant_guard.access_mode) is
  'True when the current user has `permission` with at least `mode` access in the tenant';

-- Set-returning form for policies:
--
--   tenant_id = any (array(select tenant_guard.permitted_tenant_ids('projects', 'edit')))
--
-- The array(select ...) is an uncorrelated subquery, so PostgreSQL runs it
-- once per statement as an InitPlan. `tenant_id = any (<array>)` can then use
-- an index on tenant_id. The shorter `tenant_id in (select ...)` also runs the
-- function only once, but becomes a hashed SubPlan filter, which cannot use
-- an index and scans the whole table.
create or replace function tenant_guard.permitted_tenant_ids(
  permission text,
  mode       tenant_guard.access_mode default 'view'
)
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select distinct m.tenant_id
  from tenant_guard.tenant_members m
  join tenant_guard.role_permissions rp on rp.role = m.role
  where m.user_id = tenant_guard.current_user_id()
    and rp.access >= permitted_tenant_ids.mode
    and (
      rp.permission = permitted_tenant_ids.permission
      or (rp.permission = '*' and not starts_with(permitted_tenant_ids.permission, 'tenant_guard.'))
    );
$$;

comment on function tenant_guard.permitted_tenant_ids(text, tenant_guard.access_mode) is
  'Ids of the tenants in which the current user has `permission` with at least `mode` access';

-- Write policies on the kit's own tables -------------------------------------

drop policy if exists tenants_update on tenant_guard.tenants;
create policy tenants_update on tenant_guard.tenants
  for update
  using (id = any (array(select tenant_guard.permitted_tenant_ids('tenant_guard.tenant', 'edit'))))
  with check (id = any (array(select tenant_guard.permitted_tenant_ids('tenant_guard.tenant', 'edit'))));

drop policy if exists tenant_members_insert on tenant_guard.tenant_members;
create policy tenant_members_insert on tenant_guard.tenant_members
  for insert
  with check (tenant_id = any (array(select tenant_guard.permitted_tenant_ids('tenant_guard.members', 'edit'))));

drop policy if exists tenant_members_update on tenant_guard.tenant_members;
create policy tenant_members_update on tenant_guard.tenant_members
  for update
  using (tenant_id = any (array(select tenant_guard.permitted_tenant_ids('tenant_guard.members', 'edit'))))
  with check (tenant_id = any (array(select tenant_guard.permitted_tenant_ids('tenant_guard.members', 'edit'))));

drop policy if exists tenant_members_delete on tenant_guard.tenant_members;
create policy tenant_members_delete on tenant_guard.tenant_members
  for delete
  using (tenant_id = any (array(select tenant_guard.permitted_tenant_ids('tenant_guard.members', 'edit'))));

-- ------------------------------------------------------------------------
-- sql/030_tenant_lock.sql
-- ------------------------------------------------------------------------

-- pg-tenant-guard 030: tenant lock (read-only mode).
--
-- Locking a tenant (for example when its subscription lapses) makes its data
-- read-only at the database level. A row trigger on each protected table
-- rejects INSERT, UPDATE and DELETE for rows that belong to a locked tenant,
-- while SELECT keeps working. Because it is a trigger rather than a policy,
-- the lock applies to every role, including the table owner and roles that
-- bypass RLS (such as Supabase's service_role).
--
-- Some writes must keep working while a tenant is locked: recording the
-- payment that unlocks it, requesting a data export, and so on. Each table
-- can allow-list operations when the trigger is attached:
--
--   select tenant_guard.attach_lock_trigger('public.payments', array['INSERT', 'UPDATE']);
--
-- protect_table() attaches the trigger for you and takes the same allow-list.

create table if not exists tenant_guard.tenant_locks (
  tenant_id uuid primary key references tenant_guard.tenants (id) on delete cascade,
  reason    text,
  locked_at timestamptz not null default now()
);

comment on table tenant_guard.tenant_locks is
  'Locked tenants. A row here makes the tenant read-only on every table with the lock trigger';

-- The lock state is administrative. It lives in its own table, not in a
-- column on tenants, so that no tenant-level permission (such as renaming the
-- tenant) can ever be used to unlock it. Clients get no privileges and no
-- policies on this table; they use is_locked() instead.
alter table tenant_guard.tenant_locks enable row level security;

-- Locks a tenant, or updates the reason if it is already locked (keeping the
-- original locked_at). Intended for your billing backend or admin tooling;
-- not granted to client roles.
create or replace function tenant_guard.lock_tenant(tenant_id uuid, reason text default null)
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $$
begin
  if not exists (select 1 from tenant_guard.tenants t where t.id = lock_tenant.tenant_id) then
    raise exception 'tenant % does not exist', lock_tenant.tenant_id
      using errcode = 'no_data_found';
  end if;

  insert into tenant_guard.tenant_locks (tenant_id, reason)
  values (lock_tenant.tenant_id, lock_tenant.reason)
  -- ON CONFLICT names the constraint: a bare (tenant_id) would be ambiguous
  -- with the parameter of the same name.
  on conflict on constraint tenant_locks_pkey do update set reason = excluded.reason;
end;
$$;

comment on function tenant_guard.lock_tenant(uuid, text) is
  'Makes a tenant read-only on all tables with the lock trigger';

-- Unlocks a tenant. Returns true if it was locked.
create or replace function tenant_guard.unlock_tenant(tenant_id uuid)
returns boolean
language plpgsql
volatile
security definer
set search_path = ''
as $$
begin
  delete from tenant_guard.tenant_locks l where l.tenant_id = unlock_tenant.tenant_id;
  return found;
end;
$$;

comment on function tenant_guard.unlock_tenant(uuid) is
  'Restores writes for a locked tenant; returns true if it was locked';

-- Lets the application show a "read-only" banner. Answers only for tenants
-- the current user belongs to and returns NULL otherwise, so it cannot be
-- used to probe the billing state of other tenants. Admin tooling should
-- read tenant_guard.tenant_locks directly.
create or replace function tenant_guard.is_locked(tenant_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select case
    when tenant_guard.is_member(is_locked.tenant_id)
      then exists (select 1 from tenant_guard.tenant_locks l where l.tenant_id = is_locked.tenant_id)
  end;
$$;

comment on function tenant_guard.is_locked(uuid) is
  'True if a tenant the current user belongs to is locked; NULL for other tenants';

-- Row trigger that enforces the lock. Trigger arguments are the operations
-- that stay allowed while the tenant is locked ('INSERT', 'UPDATE', 'DELETE').
--
-- For UPDATE both the old and the new tenant_id are checked, so a row can
-- neither be changed inside a locked tenant nor moved into one.
--
-- SECURITY DEFINER so it can read tenant_locks, which clients cannot.
create or replace function tenant_guard.enforce_tenant_lock()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tenant uuid;
  v_reason text;
begin
  if tg_op = any (tg_argv) then
    return case tg_op when 'DELETE' then old else new end;
  end if;

  -- OLD is NULL for INSERT and NEW is NULL for DELETE; a NULL in the list
  -- simply matches nothing.
  select l.tenant_id, l.reason
    into v_tenant, v_reason
  from tenant_guard.tenant_locks l
  where l.tenant_id in (old.tenant_id, new.tenant_id)
  limit 1;

  if v_tenant is not null then
    raise exception 'tenant % is locked: % on %.% is not allowed',
        v_tenant, tg_op, tg_table_schema, tg_table_name
      using errcode = 'read_only_sql_transaction',
            detail  = coalesce('Reason: ' || v_reason, 'No reason given.'),
            hint    = 'Reads still work. Writes resume after tenant_guard.unlock_tenant() is called.';
  end if;

  return case tg_op when 'DELETE' then old else new end;
end;
$$;

comment on function tenant_guard.enforce_tenant_lock() is
  'Trigger: rejects writes to rows of locked tenants, except the operations passed as trigger arguments';

-- Attaches (or re-attaches) the lock trigger to a table with a tenant_id
-- column. allow_when_locked lists operations that stay allowed while the
-- tenant is locked; case-insensitive.
--
-- The trigger is named tenant_guard_lock. BEFORE triggers fire in name
-- order, so a BEFORE trigger whose name sorts after it and that changes
-- tenant_id would not be re-checked. Avoid changing tenant_id in triggers.
create or replace function tenant_guard.attach_lock_trigger(
  tbl               regclass,
  allow_when_locked text[] default '{}'
)
returns void
language plpgsql
volatile
set search_path = ''
as $$
declare
  v_ops  text[];
  v_bad  text[];
  v_args text;
begin
  perform tenant_guard.assert_tenant_table(tbl);

  select coalesce(array_agg(distinct upper(btrim(op)) order by upper(btrim(op))), '{}')
    into v_ops
  from unnest(coalesce(allow_when_locked, '{}')) as op;

  select array_agg(op) into v_bad
  from unnest(v_ops) as op
  where op not in ('INSERT', 'UPDATE', 'DELETE');

  if v_bad is not null then
    raise exception 'attach_lock_trigger: unknown operation(s) %; expected INSERT, UPDATE or DELETE', v_bad
      using errcode = 'invalid_parameter_value';
  end if;

  select string_agg(format('%L', op), ', ') into v_args from unnest(v_ops) as op;

  if exists (select 1 from pg_catalog.pg_trigger t
             where t.tgrelid = tbl and t.tgname = 'tenant_guard_lock') then
    execute format('drop trigger tenant_guard_lock on %s', tbl);
  end if;

  execute format(
    'create trigger tenant_guard_lock before insert or update or delete on %s
       for each row execute function tenant_guard.enforce_tenant_lock(%s)',
    tbl, coalesce(v_args, ''));
end;
$$;

comment on function tenant_guard.attach_lock_trigger(regclass, text[]) is
  'Attaches the tenant lock trigger to a table; the array lists operations allowed while locked';

create or replace function tenant_guard.detach_lock_trigger(tbl regclass)
returns void
language plpgsql
volatile
set search_path = ''
as $$
begin
  if exists (select 1 from pg_catalog.pg_trigger t
             where t.tgrelid = tbl and t.tgname = 'tenant_guard_lock') then
    execute format('drop trigger tenant_guard_lock on %s', tbl);
  end if;
end;
$$;

comment on function tenant_guard.detach_lock_trigger(regclass) is
  'Removes the tenant lock trigger from a table';

-- ------------------------------------------------------------------------
-- sql/040_protect_table.sql
-- ------------------------------------------------------------------------

-- pg-tenant-guard 040: protect_table() applies the standard tenant policies
-- to any table that has a `tenant_id uuid` column.
--
-- These are DDL helpers for migrations, run by the table owner. They are
-- SECURITY INVOKER on purpose: running them as anyone other than the caller
-- would let a client enable or drop policies on tables it does not own.

-- Applies four policies to `tbl`:
--
--   SELECT  rows of tenants where the user has `permission` view access
--   INSERT  new rows must belong to a tenant where the user has edit access
--   UPDATE  only rows the user can edit, and the new row must still belong
--           to a tenant where the user has edit access (so tenant_id cannot
--           be changed to a tenant the user cannot edit)
--   DELETE  only rows the user can edit
--
-- It also attaches the tenant lock trigger (030_tenant_lock.sql), passing
-- `allow_when_locked` through: the operations that stay allowed on this
-- table while the tenant is locked.
--
-- `permission` defaults to the table's name (without schema), which the
-- default roles match through the '*' wildcard. Safe to call again: the
-- policies are dropped and recreated, so it also works for changing the
-- permission name.
create or replace function tenant_guard.protect_table(
  tbl               regclass,
  permission        text default null,
  allow_when_locked text[] default '{}'
)
returns void
language plpgsql
volatile
set search_path = ''
as $$
declare
  v_attnum     smallint;
  v_permission text;
  v_view_check text;
  v_edit_check text;
  v_policy     name;
begin
  v_attnum := tenant_guard.assert_tenant_table(tbl);

  select coalesce(protect_table.permission, c.relname) into v_permission
  from pg_catalog.pg_class c
  where c.oid = tbl;

  v_view_check := format(
    'tenant_id = any (array(select tenant_guard.permitted_tenant_ids(%L, %L)))', v_permission, 'view');
  v_edit_check := format(
    'tenant_id = any (array(select tenant_guard.permitted_tenant_ids(%L, %L)))', v_permission, 'edit');

  -- With search_path = '', regclass prints schema-qualified, quoted names.
  execute format('alter table %s enable row level security', tbl);

  for v_policy in
    select p.polname from pg_catalog.pg_policy p
    where p.polrelid = tbl
      and p.polname in ('tenant_guard_select', 'tenant_guard_insert',
                        'tenant_guard_update', 'tenant_guard_delete')
  loop
    execute format('drop policy %I on %s', v_policy, tbl);
  end loop;

  execute format('create policy tenant_guard_select on %s for select using (%s)',
                 tbl, v_view_check);
  execute format('create policy tenant_guard_insert on %s for insert with check (%s)',
                 tbl, v_edit_check);
  execute format('create policy tenant_guard_update on %s for update using (%s) with check (%s)',
                 tbl, v_edit_check, v_edit_check);
  execute format('create policy tenant_guard_delete on %s for delete using (%s)',
                 tbl, v_edit_check);

  perform tenant_guard.attach_lock_trigger(tbl, allow_when_locked);

  -- RLS adds a tenant_id filter to every query. Without an index that starts
  -- with tenant_id, that filter is a sequential scan.
  if not exists (
    select 1 from pg_catalog.pg_index i
    where i.indrelid = tbl and i.indkey[0] = v_attnum
  ) then
    raise notice 'protect_table: % has no index starting with tenant_id; consider: create index on % (tenant_id)',
      tbl, tbl;
  end if;
end;
$$;

comment on function tenant_guard.protect_table(regclass, text, text[]) is
  'Enables RLS and applies the tenant_guard policies and lock trigger to a table with a tenant_id uuid column';

-- Removes what protect_table() added (policies and lock trigger). Row-level
-- security stays enabled, so
-- the table becomes deny-all for client roles rather than wide open. Disable
-- it yourself if that is really what you want.
create or replace function tenant_guard.unprotect_table(tbl regclass)
returns void
language plpgsql
volatile
set search_path = ''
as $$
declare
  v_policy name;
begin
  for v_policy in
    select p.polname from pg_catalog.pg_policy p
    where p.polrelid = tbl
      and p.polname in ('tenant_guard_select', 'tenant_guard_insert',
                        'tenant_guard_update', 'tenant_guard_delete')
  loop
    execute format('drop policy %I on %s', v_policy, tbl);
  end loop;

  perform tenant_guard.detach_lock_trigger(tbl);
end;
$$;

comment on function tenant_guard.unprotect_table(regclass) is
  'Drops the tenant_guard policies and lock trigger from a table; RLS stays enabled (deny-all)';

-- Lists tables that have a tenant_id column but are not fully protected:
-- RLS is disabled, a tenant_guard policy is missing, or the lock trigger is
-- missing. Useful as a
-- check in your own migration tests:
--
--   select * from tenant_guard.unprotected_tables();  -- expect no rows
create or replace function tenant_guard.unprotected_tables()
returns setof regclass
language sql
stable
set search_path = ''
as $$
  select c.oid::regclass
  from pg_catalog.pg_class c
  join pg_catalog.pg_namespace n on n.oid = c.relnamespace
  join pg_catalog.pg_attribute a
    on a.attrelid = c.oid and a.attname = 'tenant_id' and a.attnum > 0 and not a.attisdropped
  where c.relkind in ('r', 'p')
    and not c.relispartition
    and n.nspname not in ('pg_catalog', 'information_schema', 'tenant_guard')
    and n.nspname not like 'pg\_%'
    and (
      not c.relrowsecurity
      or (
        select count(*)
        from pg_catalog.pg_policy p
        where p.polrelid = c.oid
          and p.polname in ('tenant_guard_select', 'tenant_guard_insert',
                            'tenant_guard_update', 'tenant_guard_delete')
      ) < 4
      or not exists (
        select 1 from pg_catalog.pg_trigger t
        where t.tgrelid = c.oid and t.tgname = 'tenant_guard_lock'
      )
    )
  order by c.oid::regclass::text;
$$;

comment on function tenant_guard.unprotected_tables() is
  'Tables with a tenant_id column that lack RLS, the tenant_guard policies or the lock trigger';

-- ------------------------------------------------------------------------
-- sql/090_grants.sql
-- ------------------------------------------------------------------------

-- pg-tenant-guard 090: privileges for client roles.
--
-- Nothing in tenant_guard is granted to PUBLIC. A client role (the role your
-- API runs queries as) gets exactly what it needs through grant_to(). On
-- Supabase this runs automatically for "authenticated" and "anon".

-- Functions are executable by PUBLIC by default in PostgreSQL. Take that away
-- for the whole schema; grant_to() hands back the client-facing ones.
revoke execute on all functions in schema tenant_guard from public;

create or replace function tenant_guard.grant_to(role_name name)
returns void
language plpgsql
volatile
set search_path = ''
as $$
begin
  execute format('grant usage on schema tenant_guard to %I', role_name);

  -- Column-level UPDATE: clients may rename a tenant or change a member's
  -- role, but never move a row to another tenant or rewrite its id.
  execute format('grant select, update (name) on tenant_guard.tenants to %I', role_name);
  execute format('grant select, insert, update (role), delete on tenant_guard.tenant_members to %I', role_name);
  execute format('grant select on tenant_guard.roles, tenant_guard.role_permissions to %I', role_name);
  execute format('grant usage on type tenant_guard.access_mode to %I', role_name);

  execute format(
    'grant execute on function
       tenant_guard.current_user_id(),
       tenant_guard.is_member(uuid),
       tenant_guard.member_role(uuid),
       tenant_guard.my_tenant_ids(),
       tenant_guard.create_tenant(text),
       tenant_guard.has_permission(uuid, text, tenant_guard.access_mode),
       tenant_guard.permitted_tenant_ids(text, tenant_guard.access_mode),
       tenant_guard.is_locked(uuid)
     to %I', role_name);
end;
$$;

comment on function tenant_guard.grant_to(name) is
  'Grants a client role the privileges it needs to use tenant_guard from RLS policies and the API';

revoke all on function tenant_guard.grant_to(name) from public;

-- Supabase: grant to the API roles when they exist. "anon" needs the grants
-- too: policies on your tables call tenant_guard functions, and a missing
-- privilege would turn "no rows" into a permission error for anonymous requests.
do $$
declare
  r name;
begin
  foreach r in array array['authenticated', 'anon']::name[] loop
    if exists (select 1 from pg_roles where rolname = r) then
      perform tenant_guard.grant_to(r);
    end if;
  end loop;
end;
$$;

commit;
